CELL = 288          # one badge cell on the sheet (CSS px): the badge itself is 208, the rest is room for its edge and shadow
COLS = 6
RIB_W, RIB_H = 460, 150
SMALL = 144

def tile_html(i, name, label, icon, a, b):
    x, y = (i % COLS) * CELL, (i // COLS) * CELL
    small = ' small' if '<br>' in label else ' mid' if len(label) > 9 else ''
    big = ' big' if not label else ''
    return f'''<div class="cell" style="left:{x}px;top:{y}px"><div class="badge" style="--a:{a};--b:{b}"><div class="grain"></div>
  <svg class="icon{big}" viewBox="0 0 24 24">{ICONS[icon]}</svg><div class="label{small}">{label}</div></div></div>'''

def build_html():
    rows = (len(TILES) + COLS - 1) // COLS
    y_rib = rows * CELL
    y_small = y_rib + RIB_H
    height = y_small + SMALL
    rects, parts = {}, []
    for i, t in enumerate(TILES):
        parts.append(tile_html(i, *t))
        rects[t[0]] = ((i % COLS) * CELL, (i // COLS) * CELL, CELL, CELL)
    star = f'<svg class="star" viewBox="0 0 24 24"><path d="M12 2.2l2.7 6 6.5.7-4.9 4.4 1.4 6.4-5.7-3.3-5.7 3.3 1.4-6.4-4.9-4.4 6.5-.7z" fill="#FFDD66" stroke="{INK}" stroke-width="1.6" stroke-linejoin="round"/><path d="M9.2 8.2c.6-1.3 1.3-2.3 2-3" stroke="#FFF8EA" stroke-width="1.4" stroke-linecap="round" fill="none"/></svg>'
    spark = '<svg class="star" viewBox="0 0 24 24"><path d="M12 1.5l2.4 8.1 8.1 2.4-8.1 2.4-2.4 8.1-2.4-8.1-8.1-2.4 8.1-2.4z" fill="#FFFDF2"/></svg>'
    for k, (n, body) in enumerate((('star', star), ('spark', spark), ('glow', '<div class="glow"></div>'))):
        parts.append(f'<div class="cell" style="left:{k * SMALL}px;top:{y_small}px;width:{SMALL}px;height:{SMALL}px">{body}</div>')
        rects[n] = (k * SMALL, y_small, SMALL, SMALL)
    parts.append(f'<div class="cell" style="left:{4 * SMALL}px;top:{y_small}px;width:{5 * RIB_W - 4 * SMALL}px;height:{SMALL}px"><div class="logo"><svg viewBox="0 0 24 24"><path d="M12 2.2l2.7 6 6.5.7-4.9 4.4 1.4 6.4-5.7-3.3-5.7 3.3 1.4-6.4-4.9-4.4 6.5-.7z" fill="#FFDD66" stroke="{INK}" stroke-width="1.6" stroke-linejoin="round"/></svg><span>Bambi</span></div></div>')
    rects['logo'] = (4 * SMALL, y_small, 5 * RIB_W - 4 * SMALL, SMALL)
    y_extra = height
    height += RIB_H
    cut = f'stroke="{CREAM}" stroke-width="4.4" stroke-linejoin="round" fill="{CREAM}"'
    mob = f'<svg class="star" viewBox="-1.5 -1.5 27 27"><path d="{MONSTER_BODY}" {cut}/>{MONSTER}</svg>'
    gem_d = 'M7 3.6h10l4.4 5.6L12 21 2.6 9.2z'
    gem = (f'<svg class="star" viewBox="-1.5 -1.5 27 27"><path d="{gem_d}" {cut}/><path d="{gem_d}" fill="#8FD3F4" stroke="{INK}" stroke-width="1.6" stroke-linejoin="round"/>'
           f'<path d="M7 3.6l2.4 5.6L12 21l2.6-11.8L17 3.6" fill="#BFE8FB" stroke="{INK}" stroke-width="1.1" stroke-linejoin="round"/><path d="M2.6 9.2h18.8" stroke="{INK}" stroke-width="1.1" fill="none"/></svg>')
    heart_d = 'M12 20.6C5.4 15.6 2.6 12.3 2.6 8.6a4.9 4.9 0 0 1 9.4-1.9 4.9 4.9 0 0 1 9.4 1.9c0 3.7-2.8 7-9.4 12z'
    heart = (f'<svg class="star" viewBox="-1.5 -1.5 27 27"><path d="{heart_d}" {cut}/><path d="{heart_d}" fill="#FF9B85" stroke="{INK}" stroke-width="1.6" stroke-linejoin="round"/>'
             f'<path d="M6.2 8.2c.2-1.2 1-2 2.2-2.2" stroke="{CREAM}" stroke-width="1.4" stroke-linecap="round" fill="none"/></svg>')
    for k, (n, body) in enumerate((('mob', mob), ('gem', gem), ('heart', heart))):
        parts.append(f'<div class="cell" style="left:{k * SMALL}px;top:{y_extra}px;width:{SMALL}px;height:{SMALL}px">{body}</div>')
        rects[n] = (k * SMALL, y_extra, SMALL, SMALL)
    # what the partner hammers at while it makes something, and its hammer
    parcel = (f'<svg class="star" viewBox="-1.5 -1.5 27 27"><rect x="3.6" y="9" width="16.8" height="11.6" rx="1.8" fill="#FFD9A0" stroke="{INK}" stroke-width="1.6"/>'
              f'<rect x="2.4" y="5.8" width="19.2" height="4.4" rx="1.5" fill="#FFAE6B" stroke="{INK}" stroke-width="1.6"/>'
              f'<rect x="10.5" y="5.8" width="3" height="14.8" fill="#F8B4C8" stroke="{INK}" stroke-width="1.2"/>'
              f'<path d="M12 5.8c-1.7-3.6-5.6-3.3-5.2-.9.3 1.7 3.1 1.6 5.2.9zM12 5.8c1.7-3.6 5.6-3.3 5.2-.9-.3 1.7-3.1 1.6-5.2.9z" fill="#F8B4C8" stroke="{INK}" stroke-width="1.3" stroke-linejoin="round"/></svg>')
    hammer = (f'<svg class="star" viewBox="-1.5 -1.5 27 27"><g transform="rotate(38 12 12)"><rect x="10.8" y="8.4" width="2.6" height="13.4" rx="1.3" fill="#D9A066" stroke="{INK}" stroke-width="1.4"/>'
              f'<rect x="5" y="3.2" width="13" height="6.4" rx="1.7" fill="#C3CEDD" stroke="{INK}" stroke-width="1.6"/><path d="M6.6 5h3.4" stroke="{CREAM}" stroke-width="1.2" stroke-linecap="round"/></g></svg>')
    for k, (n, body) in enumerate((('parcel', parcel), ('hammer', hammer))):
        parts.append(f'<div class="cell" style="left:{2 * RIB_W + k * SMALL}px;top:{y_extra}px;width:{SMALL}px;height:{SMALL}px">{body}</div>')
        rects[n] = (2 * RIB_W + k * SMALL, y_extra, SMALL, SMALL)
    # a place's preview on its tile: hills and a far ridge, white - the app tints them with the place's own colour and
    # lays them on a disc that runs from its sky colour to its horizon colour
    hills = ('<svg viewBox="0 0 24 24" style="position:absolute;inset:0;width:100%;height:100%"><defs><clipPath id="hc"><circle cx="12" cy="12" r="11.1"/></clipPath></defs><g clip-path="url(#hc)">'
             '<circle cx="16.6" cy="8.2" r="2.7" fill="#fff" opacity=".92"/>'
             '<path d="M-1 16.5c3-3.6 5.6-4.6 8-2.2 2.2-3.4 5.2-4.4 8.2-1.6 2.6-2 5.6-1.4 9.8 2.4V25H-1z" fill="#fff" opacity=".55"/>'
             '<path d="M-1 19.6c4.2-2.6 8-2.8 11.6-.8 4.4-2.4 9-2 14.4 1V25H-1z" fill="#fff"/></g></svg>')
    parts.append(f'<div class="cell" style="left:{2 * RIB_W + 2 * SMALL}px;top:{y_extra}px;width:{SMALL}px;height:{SMALL}px">{hills}</div>')
    rects['place-hills'] = (2 * RIB_W + 2 * SMALL, y_extra, SMALL, SMALL)
    parts.append(f'<div class="cell" style="left:{RIB_W}px;top:{y_extra}px;width:{RIB_W}px;height:{RIB_H}px"><div class="ribbon"><span>Marketplace</span></div></div>')
    rects['market-ribbon'] = (RIB_W, y_extra, RIB_W, RIB_H)
    # the ribbon over the menu fan: the same ribbon with nothing written on it (the app writes the page's name: Bag, Bambi, Tools, Help)
    parts.append(f'<div class="cell" style="left:{3 * RIB_W}px;top:{y_extra}px;width:{RIB_W}px;height:{RIB_H}px"><div class="ribbon"><span></span></div></div>')
    rects['menu-ribbon'] = (3 * RIB_W, y_extra, RIB_W, RIB_H)
    width = max(COLS * CELL, 5 * RIB_W)
    font_url = 'file:///' + FONT.replace('\\', '/')
    css = '''
@font-face{font-family:"Jua";src:url("%s");}
html,body{margin:0;background:transparent;}
body{width:%dpx;height:%dpx;position:relative;overflow:hidden;font-family:"Jua","Segoe UI",sans-serif;color:%s;}
.cell{position:absolute;width:%dpx;height:%dpx;}
.badge{position:absolute;left:40px;top:30px;width:208px;height:208px;box-sizing:border-box;border-radius:50%%;border:6px solid %s;overflow:hidden;
  background:radial-gradient(circle at 32%% 24%%,color-mix(in srgb,var(--a) 55%%,#fff) 0%%,var(--a) 42%%,var(--b) 100%%);
  box-shadow:0 0 0 9px %s,0 0 0 11.5px rgba(74,47,39,.20),0 13px 16px 6px rgba(74,47,39,.26);
  display:flex;flex-direction:column;align-items:center;justify-content:center;}
.badge::before{content:"";position:absolute;left:26px;top:15px;width:74px;height:34px;border-radius:50%%;background:rgba(255,255,255,.62);transform:rotate(-28deg);}
.badge::after{content:"";position:absolute;left:0;right:0;bottom:0;height:46%%;background:linear-gradient(180deg,rgba(74,47,39,0),rgba(74,47,39,.10));}
.grain{position:absolute;inset:0;opacity:.20;mix-blend-mode:multiply;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' seed='4'/><feColorMatrix values='0 0 0 0 .45  0 0 0 0 .32  0 0 0 0 .26  0 0 0 .9 0'/></filter><rect width='220' height='220' filter='url(%%23n)'/></svg>");}
.icon{width:104px;height:104px;position:relative;z-index:1;margin-top:-4px;filter:drop-shadow(0 3px 0 rgba(74,47,39,.16));}
.label{position:relative;z-index:1;font-size:30px;line-height:1.0;text-align:center;margin-top:1px;letter-spacing:.2px;text-shadow:0 1.5px 0 rgba(255,248,234,.75);}
.icon.big{width:150px;height:150px;margin-top:0;}
.label.small{font-size:21px;margin-top:-2px;}
.label.mid{font-size:24px;}
.ribbon{position:absolute;left:50px;top:22px;width:360px;height:74px;background:%s;border:5px solid %s;box-sizing:border-box;border-radius:14px;
  box-shadow:0 8px 10px 2px rgba(74,47,39,.24);display:flex;align-items:center;justify-content:center;}
.ribbon::before,.ribbon::after{content:"";position:absolute;top:14px;width:44px;height:60px;background:#F3DFAE;border:5px solid %s;box-sizing:border-box;z-index:-1;}
.ribbon::before{left:-30px;clip-path:polygon(0 0,100%% 0,100%% 100%%,0 100%%,34%% 50%%);border-radius:6px;}
.ribbon::after{right:-30px;clip-path:polygon(0 0,100%% 0,66%% 50%%,100%% 100%%,0 100%%);border-radius:6px;}
.ribbon span{font-size:44px;letter-spacing:.5px;}
.dots{position:absolute;left:0;right:0;top:112px;display:flex;justify-content:center;gap:14px;}
.dots b{width:15px;height:15px;border-radius:50%%;background:%s;border:3.5px solid %s;box-sizing:border-box;opacity:.85;}
.dots b.on{background:#FFD05A;width:21px;height:21px;margin-top:-3px;opacity:1;}
.star{position:absolute;inset:12px;filter:drop-shadow(0 3px 2px rgba(74,47,39,.25));}
.logo{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:14px;}
.logo svg{width:104px;height:104px;filter:drop-shadow(0 4px 3px rgba(74,47,39,.28));}
.logo span{font-size:112px;letter-spacing:1px;color:#FFF8EA;-webkit-text-stroke:9px #4A2F27;paint-order:stroke fill;text-shadow:0 7px 0 rgba(74,47,39,.22);}
.glow{position:absolute;inset:0;border-radius:50%%;background:radial-gradient(closest-side,rgba(255,255,255,.95),rgba(255,255,255,.35) 38%%,rgba(255,255,255,0) 100%%);}
''' % (font_url, width, height, INK, CELL, CELL, INK, CREAM, CREAM, INK, INK, CREAM, INK)
    html = f'<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head><body>{"".join(parts)}</body></html>'
    return html, rects, width, height

def browser():
    for p in (r'C:\Program Files\Google\Chrome\Application\chrome.exe', r'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe', r'C:\Program Files\Microsoft\Edge\Application\msedge.exe'):
        if os.path.exists(p): return p
    raise SystemExit('no Chrome / Edge found')

def main():
    html, rects, width, height = build_html()
    page = os.path.join(HERE, 'sheet.html')
    open(page, 'w', encoding='utf-8').write(html)
    shot = os.path.join(HERE, 'sheet.png')
    if os.path.exists(shot): os.remove(shot)
    profile = tempfile.mkdtemp(prefix='lp-ui-art-')
    try:
        subprocess.run([browser(), '--headless=new', '--disable-gpu', '--hide-scrollbars', '--no-first-run', '--allow-file-access-from-files', f'--user-data-dir={profile}',
                        f'--force-device-scale-factor={SCALE}', f'--window-size={width},{height}', '--default-background-color=00000000', '--virtual-time-budget=3000',
                        f'--screenshot={shot}', 'file:///' + page.replace('\\', '/')], check=False, timeout=120, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    finally:
        shutil.rmtree(profile, ignore_errors=True)
    if not os.path.exists(shot): raise SystemExit('the browser did not write the picture')
    sheet = Image.open(shot).convert('RGBA')
    print('sheet', sheet.size, 'expected', (width * SCALE, height * SCALE))
    os.makedirs(OUT, exist_ok=True)
    import glass_art                                    # the pictures of the glass games and the PC shows: a sheet of their own (glass_art.py)
    keep = set(n + '.png' for n in rects) | set(n + '.png' for n in glass_art.NAMES)
    for old in os.listdir(OUT):
        if old.endswith('.png') and old not in keep:
            os.remove(os.path.join(OUT, old))
            if os.path.exists(os.path.join(OUT, old + '.meta')): os.remove(os.path.join(OUT, old + '.meta'))
    for name, (x, y, w, h) in rects.items():
        im = sheet.crop((x * SCALE, y * SCALE, (x + w) * SCALE, (y + h) * SCALE))
        if name.startswith('tile-') or name.startswith('rps-') or name.startswith('item-') or name.startswith('skill-'): im = im.resize((384, 384), Image.LANCZOS)
        elif name in ('logo', 'market-ribbon', 'menu-ribbon'): im = im.resize((512, round(512 * h / w)), Image.LANCZOS)
        else: im = im.resize((192, 192), Image.LANCZOS)
        im.save(os.path.join(OUT, name + '.png'))
    print('wrote', len(rects), 'pictures to', OUT)
    print('wrote', glass_art.build(browser(), FONT, OUT, HERE), 'glass pictures (glass-*.png)')

if __name__ == '__main__':
    main()
